#!/usr/bin/env node

/**
 * Deploy LOCAL Drop-in Sports Features
 * Community Centers, Parks, Gymnasiums, Arenas
 */

const fs = require('fs').promises;
const { exec } = require('child_process');

// Create LOCAL venues endpoint
async function createVenuesEndpoint() {
    console.log('🏟️ Creating LOCAL venues endpoint...');

    const venuesRoute = `const express = require('express');
const router = express.Router();

// LOCAL venues - Community Centers, Parks, Gymnasiums, Arenas  
const LOCAL_VENUES = [
    { id: 1, name: 'Killarney Community Centre', type: 'community_center', city: 'Vancouver', sports: ['soccer', 'basketball', 'volleyball'], address: '6260 Killarney Street' },
    { id: 2, name: 'Trout Lake Community Centre', type: 'community_center', city: 'Vancouver', sports: ['hockey', 'skating', 'basketball'], address: '3350 Victoria Drive' },
    { id: 3, name: 'Hillcrest Community Centre', type: 'community_center', city: 'Vancouver', sports: ['swimming', 'basketball', 'badminton'], address: '4575 Clancy Loranger Way' },
    { id: 4, name: 'Queen Elizabeth Park', type: 'park', city: 'Vancouver', sports: ['tennis', 'soccer'], address: '4600 Cambie Street' },
    { id: 5, name: 'UBC War Memorial Gym', type: 'gymnasium', city: 'Vancouver', sports: ['basketball', 'volleyball', 'badminton'], address: '6081 University Boulevard' },
    { id: 6, name: 'Britannia Ice Rink', type: 'arena', city: 'Vancouver', sports: ['hockey', 'skating'], address: '1661 Napier Street' }
];

router.get('/', (req, res) => {
    const { city, sport, type } = req.query;
    let venues = [...LOCAL_VENUES];

    if (city) venues = venues.filter(v => v.city.toLowerCase().includes(city.toLowerCase()));
    if (sport) venues = venues.filter(v => v.sports.includes(sport.toLowerCase()));
    if (type) venues = venues.filter(v => v.type === type);

    res.json({
        success: true,
        count: venues.length,
        venues: venues.map(v => ({
            ...v,
            dropInAvailable: true,
            openHours: '6 AM - 10 PM'
        }))
    });
});

router.get('/:id', (req, res) => {
    const venue = LOCAL_VENUES.find(v => v.id === parseInt(req.params.id));
    if (!venue) return res.status(404).json({ error: 'Venue not found' });

    res.json({
        success: true,
        venue: {
            ...venue,
            dropInSchedule: {
                monday: ['7-9 AM', '7-9 PM'],
                tuesday: ['7-9 AM', '7-9 PM'],
                saturday: ['9 AM - 5 PM']
            }
        }
    });
});

module.exports = router;`;

    await fs.writeFile('mockup/backend/routes/venues.js', venuesRoute);
    console.log('✅ Created venues endpoint');
}

// Create LOCAL sports endpoint
async function createSportsEndpoint() {
    console.log('🏃 Creating LOCAL sports endpoint...');

    const sportsRoute = `const express = require('express');
const router = express.Router();

const LOCAL_SPORTS = [
    { id: 'basketball', name: 'Basketball', emoji: '🏀', dropInVenues: 15, type: 'indoor' },
    { id: 'soccer', name: 'Soccer', emoji: '⚽', dropInVenues: 20, type: 'outdoor' },
    { id: 'volleyball', name: 'Volleyball', emoji: '🏐', dropInVenues: 12, type: 'indoor' },
    { id: 'hockey', name: 'Ice Hockey', emoji: '🏒', dropInVenues: 8, type: 'arena' },
    { id: 'skating', name: 'Public Skating', emoji: '⛸️', dropInVenues: 8, type: 'arena' },
    { id: 'badminton', name: 'Badminton', emoji: '🏸', dropInVenues: 10, type: 'indoor' }
];

router.get('/', (req, res) => {
    res.json({
        success: true,
        count: LOCAL_SPORTS.length,
        sports: LOCAL_SPORTS.map(s => ({
            ...s,
            description: 'Drop-in ' + s.name + ' at local venues',
            avgCost: s.type === 'arena' ? '$8-12' : '$3-8'
        }))
    });
});

router.get('/:id', (req, res) => {
    const sport = LOCAL_SPORTS.find(s => s.id === req.params.id);
    if (!sport) return res.status(404).json({ error: 'Sport not found' });

    res.json({
        success: true,
        sport: {
            ...sport,
            venues: sport.dropInVenues + ' local venues',
            peakTimes: ['6-8 AM', '7-9 PM']
        }
    });
});

module.exports = router;`;

    await fs.writeFile('mockup/backend/routes/sports.js', sportsRoute);
    console.log('✅ Created sports endpoint');
}

// Deploy to Railway
async function deployToRailway() {
    console.log('🚀 Deploying to Railway...');

    return new Promise((resolve, reject) => {
        const commands = [
            'git add .',
            'git commit -m "🚀 FORCE DEPLOY: All LOCAL drop-in sports endpoints\\n\\n- Added venues with community centers, parks, gyms\\n- Added sports endpoint\\n- Ready for local drop-in games"',
            'git push origin main'
        ];

        exec(commands.join(' && '), (error, stdout, stderr) => {
            if (error && !error.message.includes('nothing to commit')) {
                console.error('Deploy error:', error.message);
                reject(error);
            } else {
                console.log('✅ Deployed to Railway');
                console.log(stdout);
                resolve();
            }
        });
    });
}

// Test live deployment
async function testLive() {
    console.log('\\n🧪 Testing live deployment...');

    const https = require('https');

    const test = (path) => new Promise((resolve) => {
        console.log('Testing: ' + path);
        https.get('https://findingsports.com' + path, (res) => {
            const success = res.statusCode >= 200 && res.statusCode < 400;
            console.log('  ' + (success ? '✅' : '❌') + ' ' + res.statusCode);
            resolve(success);
        }).on('error', () => {
            console.log('  ❌ Error');
            resolve(false);
        });
    });

    const results = [];
    results.push(await test('/api/venues'));
    results.push(await test('/api/sports'));
    results.push(await test('/api/venues?city=vancouver'));

    const passed = results.filter(r => r).length;
    console.log('\\n📊 Results: ' + passed + '/' + results.length + ' working');

    return passed === results.length;
}

// Main deployment
async function main() {
    console.log('🏟️ DEPLOYING LOCAL DROP-IN SPORTS FEATURES\\n');

    try {
        await createVenuesEndpoint();
        await createSportsEndpoint();
        await deployToRailway();

        console.log('\\n⏳ Waiting 90 seconds for deployment...');
        await new Promise(resolve => setTimeout(resolve, 90000));

        const success = await testLive();

        if (success) {
            console.log('\\n🎉 ALL LOCAL SPORTS ENDPOINTS WORKING!');
            console.log('🌐 https://findingsports.com/api/venues');
            console.log('🏀 https://findingsports.com/api/sports');
        } else {
            console.log('\\n⚠️  Still deploying...');
        }

    } catch (error) {
        console.error('❌ Error:', error.message);
    }
}

main();

#!/usr/bin/env node

/**
 * Emergency Railway Deployment Test
 * Creates and deploys a minimal server to verify Railway is working
 */

const { exec } = require('child_process');
const fs = require('fs').promises;
const path = require('path');

async function createMinimalServer() {
    console.log('🚨 Creating emergency minimal server for testing...\n');

    // Create a minimal server that definitely works
    const minimalServer = `
const express = require('express');
const path = require('path');
const app = express();
const PORT = process.env.PORT || 8080;

// Enable CORS
app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    next();
});

// Health check endpoint
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        message: 'Emergency server running',
        timestamp: new Date().toISOString(),
        port: PORT,
        env: process.env.NODE_ENV || 'development'
    });
});

// Root endpoint
app.get('/', (req, res) => {
    res.send(\`
        <!DOCTYPE html>
        <html>
        <head>
            <title>Finding Sports - Emergency Server</title>
            <style>
                body { font-family: Arial, sans-serif; padding: 40px; }
                .status { padding: 20px; background: #f0f0f0; border-radius: 8px; }
                .ok { color: green; }
                .error { color: red; }
            </style>
        </head>
        <body>
            <h1>Finding Sports - Emergency Server</h1>
            <div class="status">
                <p class="ok">✅ Server is running!</p>
                <p>This is a minimal emergency server to verify Railway deployment.</p>
                <p>Time: \${new Date().toISOString()}</p>
                <p>Port: \${PORT}</p>
                <h3>Test Endpoints:</h3>
                <ul>
                    <li><a href="/health">/health</a> - Health check</li>
                    <li><a href="/api/test">/api/test</a> - API test</li>
                </ul>
                <h3>Next Steps:</h3>
                <ol>
                    <li>✅ Railway deployment is working</li>
                    <li>Set JWT_SECRET in Railway environment variables</li>
                    <li>Deploy the full server.js</li>
                </ol>
            </div>
        </body>
        </html>
    \`);
});

// Test API endpoint
app.get('/api/test', (req, res) => {
    res.json({
        message: 'API is working',
        timestamp: new Date().toISOString(),
        headers: req.headers
    });
});

// Catch all for debugging
app.use('*', (req, res) => {
    console.log(\`404: \${req.method} \${req.originalUrl}\`);
    res.status(404).json({
        error: 'Not found',
        path: req.originalUrl,
        method: req.method,
        message: 'Emergency server - endpoint not implemented'
    });
});

// Start server
const server = app.listen(PORT, '0.0.0.0', () => {
    console.log(\`🚨 Emergency server running on port \${PORT}\`);
    console.log(\`Environment: \${process.env.NODE_ENV || 'development'}\`);
    console.log(\`Railway deployment: \${process.env.RAILWAY_ENVIRONMENT || 'unknown'}\`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});
`;

    // Save the emergency server
    await fs.writeFile('mockup/backend/server-emergency-test.js', minimalServer);
    console.log('✅ Created emergency test server\n');

    // Update Procfile to use emergency server
    await fs.writeFile('Procfile', 'web: cd mockup/backend && node server-emergency-test.js\n');
    console.log('✅ Updated Procfile to use emergency server\n');

    // Create minimal package.json if needed
    const minimalPackage = {
        "name": "finding-sports-backend",
        "version": "1.0.0",
        "description": "Finding Sports Backend - Emergency Test",
        "main": "server-emergency-test.js",
        "scripts": {
            "start": "node server-emergency-test.js"
        },
        "dependencies": {
            "express": "^4.18.2"
        },
        "engines": {
            "node": ">=18.0.0"
        }
    };

    await fs.writeFile(
        'mockup/backend/package-emergency.json', 
        JSON.stringify(minimalPackage, null, 2)
    );

    return true;
}

async function deployEmergencyServer() {
    try {
        await createMinimalServer();

        console.log('📦 Committing emergency server...\n');

        const commands = [
            'git add .',
            'git commit -m "🚨 EMERGENCY: Deploy minimal test server to verify Railway\n\nThis deploys a minimal Express server to test if Railway deployment is working.\nOnce confirmed, we can deploy the full server."',
            'git push origin main'
        ];

        for (const cmd of commands) {
            console.log(`Running: ${cmd}`);
            await new Promise((resolve, reject) => {
                exec(cmd, (error, stdout, stderr) => {
                    if (error) {
                        console.error(`Error: ${error.message}`);
                        reject(error);
                    } else {
                        console.log(stdout);
                        resolve(stdout);
                    }
                });
            });
        }

        console.log('\n✅ Emergency server deployed!\n');
        console.log('⏳ Wait 2-3 minutes for Railway to build and deploy\n');
        console.log('Then test these URLs:');
        console.log('  - https://findingsports-production.up.railway.app/');
        console.log('  - https://findingsports-production.up.railway.app/health');
        console.log('  - https://findingsports-production.up.railway.app/api/test');

        // Wait a bit then start testing
        console.log('\n⏳ Waiting 2 minutes before testing...');
        await new Promise(resolve => setTimeout(resolve, 120000));

        // Test the deployment
        console.log('\n🔍 Testing emergency deployment...\n');
        const https = require('https');

        const testUrl = 'https://findingsports-production.up.railway.app/health';
        https.get(testUrl, (res) => {
            console.log(`Status: ${res.statusCode}`);
            if (res.statusCode === 200) {
                console.log('✅ Emergency server is working!');
                console.log('\nNext steps:');
                console.log('1. Set JWT_SECRET in Railway environment');
                console.log('2. Update Procfile to use server.js');
                console.log('3. Push the full server deployment');
            } else {
                console.log('❌ Emergency server not responding correctly');
                console.log('Check Railway logs for errors');
            }
        }).on('error', (err) => {
            console.error('❌ Failed to reach server:', err.message);
        });

    } catch (error) {
        console.error('Failed to deploy emergency server:', error);
    }
}

// Run the emergency deployment
deployEmergencyServer();

const express = require('express');
