                    const success = res.statusCode >= 200 && res.statusCode < 400;
                    const result = {
                        name,
                        url: fullUrl,
                        method,
                        status: res.statusCode,
                        statusText: res.statusMessage,
                        success,
                        responseTime,
                        headers: res.headers,
                        data: parsedData || responseData,
                        timestamp: new Date().toISOString()
                    };

                    if (success) {
                        console.log(`   ✅ PASSED`);
                    } else {
                        console.log(`   ❌ FAILED`);
                        this.criticalFailures.push(result);
