                    name,
                    url: fullUrl,
                    method,
                    success: false,
                    error: err.message,
                    timestamp: new Date().toISOString()
                };
                this.criticalFailures.push(result);
                this.proofData.push(result);
                resolve(result);
            });

            req.on('timeout', () => {
                req.destroy();
                console.log(`   ❌ TIMEOUT after 15s`);
                const result = {
                    name,
                    url: fullUrl,
                    method,
                    success: false,
                    error: 'Timeout',
                    timestamp: new Date().toISOString()
                };
                this.criticalFailures.push(result);
                this.proofData.push(result);
                resolve(result);
            });

            if (body) {
