/**
 * Test the actual live site at findingsports.com
 */

const https = require('https');

const LIVE_SITE = 'https://findingsports.com';

async function testEndpoint(path, method = 'GET') {
    return new Promise((resolve) => {
        const url = LIVE_SITE + path;
        console.log(`\nTesting ${method} ${url}`);

        const options = {
            method: method,
            headers: {
                'User-Agent': 'Mozilla/5.0 (compatible; FindingSportsTest/1.0)',
                'Accept': 'application/json, text/html'
            },
            timeout: 10000
        };

        const req = https.request(url, options, (res) => {
            let data = '';

            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                console.log(`Status: ${res.statusCode}`);
                console.log(`Content-Type: ${res.headers['content-type']}`);
                console.log(`Server: ${res.headers['server']}`);

                if (res.statusCode === 200) {
                    console.log('✅ Success!');
                    if (data.length < 500 && res.headers['content-type']?.includes('json')) {
                        console.log('Response:', data);
                    } else {
                        console.log(`Response length: ${data.length} bytes`);
                    }
                } else {
                    console.log('❌ Failed');
                    if (data.length < 500) {
                        console.log('Response:', data);
                    }
                }

                resolve({
                    path,
                    status: res.statusCode,
                    success: res.statusCode === 200,
                    contentType: res.headers['content-type'],
                    data: data
                });
            });
        });

        req.on('error', (err) => {
            console.log(`❌ Error: ${err.message}`);
            resolve({
                path,
                success: false,
                error: err.message
            });
        });

        req.on('timeout', () => {
            req.destroy();
            console.log('❌ Timeout');
            resolve({
                path,
                success: false,
                error: 'Timeout'
            });
        });

        req.end();
    });
}

